import struct, pathlib
for path in pathlib.Path('font-corpus').iterdir():
    data=path.read_bytes()
    if len(data)<12: continue
    sfnt=data[:4]
    if sfnt in [b'\x00\x01\x00\x00',b'OTTO',b'ttcf',b'true']:
        n=struct.unpack('>H',data[4:6])[0] if sfnt!=b'ttcf' else 0
        tags=[]
        if sfnt!=b'ttcf' and 12+16*n<=len(data):
            for i in range(n): tags.append(data[12+16*i:16+16*i])
        if b'CPAL' in tags or b'COLR' in tags:
            print(path, sfnt, n, [t.decode('latin1') for t in tags if t in (b'CPAL',b'COLR')])
